package smp.aeternum.carpet.client;

import com.google.gson.Gson;import com.google.gson.reflect.TypeToken;import net.minecraft.client.gui.DrawContext;import net.minecraft.client.gui.screen.Screen;import net.minecraft.client.gui.widget.ButtonWidget;import net.minecraft.client.gui.widget.TextFieldWidget;import net.minecraft.text.Text;import smp.aeternum.carpet.actions.CommandPack;import java.lang.reflect.Type;import java.util.ArrayList;import java.util.Comparator;import java.util.List;

/** Package catalog with real controls per row and a local title filter. */
public final class CommandPacksScreen extends Screen {
 private static final Gson GSON=new Gson();private static final Type TYPE=new TypeToken<List<CommandPack>>(){}.getType();private List<CommandPack> packs;private boolean canEdit;private int scroll;private boolean draggingScrollbar;private String runFeedback="";private TextFieldWidget filter;private final List<ButtonWidget> playButtons=new ArrayList<>(),deleteButtons=new ArrayList<>();
 public CommandPacksScreen(String json,boolean canEdit){super(Text.literal("Acciones"));packs=decode(json);this.canEdit=canEdit;}public void replaceData(String json,boolean canEdit){packs=decode(json);this.canEdit=canEdit;}
 @Override protected void init(){clearChildren();playButtons.clear();deleteButtons.clear();int l=width/2-205,t=height/2-150;filter=new TextFieldWidget(textRenderer,l+14,t+56,382,18,Text.literal("Filtrar paquetes"));filter.setMaxLength(80);filter.setChangedListener(s->scroll=0);addDrawableChild(filter);ButtonWidget add=ButtonWidget.builder(Text.literal("+ Nuevo paquete"),b->{CommandPack p=new CommandPack();packs.add(p);client.setScreen(new CommandPackEditorScreen(this,packs,p,canEdit));}).dimensions(width/2-75,height/2+136,150,20).build();add.active=canEdit;addDrawableChild(add);
  for(int row=0;row<10;row++){final int r=row;ButtonWidget play=ButtonWidget.builder(Text.literal("▶"),b->runRow(r)).dimensions(0,0,20,18).build();ButtonWidget del=ButtonWidget.builder(Text.literal("X"),b->deleteRow(r)).dimensions(0,0,20,18).build();playButtons.add(play);deleteButtons.add(del);addDrawableChild(play);addDrawableChild(del);}}
 private List<CommandPack> shown(){String q=filter==null?"":filter.getText().strip().toLowerCase();return q.isEmpty()?packs:packs.stream().filter(p->p.name!=null&&p.name.toLowerCase().contains(q)).toList();}
 private void runRow(int row){List<CommandPack> visible=shown();int i=row+scroll;if(i<visible.size()){CommandPacksRequest.run(visible.get(i));runFeedback="Ejecutando paquete…";}}
 private void deleteRow(int row){if(!canEdit||!hasShiftDown())return;List<CommandPack> visible=shown();int i=row+scroll;if(i<visible.size()){packs.remove(visible.get(i));CommandPacksRequest.save(packs);scroll=Math.min(scroll,Math.max(0,shown().size()-10));}}
 @Override public void renderBackground(DrawContext c,int x,int y,float d){}
 @Override public void render(DrawContext c,int mx,int my,float d){c.fill(0,0,width,height,0x90000000);int l=width/2-205,t=height/2-150;c.fill(l,t,l+410,t+300,0xE0101010);c.drawBorder(l,t,410,300,0xFF909090);c.drawTextWithShadow(textRenderer,"PAQUETES DE ACCIONES",l+14,t+14,0xFFFFFFFF);c.drawTextWithShadow(textRenderer,"×",l+390,t+14,0xFFFFFFFF);c.drawTextWithShadow(textRenderer,canEdit?"Selecciona un paquete para editarlo o ejecutarlo":"Selecciona un paquete para ver o ejecutar",l+14,t+29,0xFFAAAAAA);c.drawTextWithShadow(textRenderer,"FILTRAR POR TÍTULO",l+14,t+44,0xFF8F8F8F);if(filter.getText().isBlank()&&!filter.isFocused())c.drawTextWithShadow(textRenderer,"Escribe para buscar paquetes…",l+20,t+61,0xFF666666);
  List<CommandPack> visiblePacks=shown();if(visiblePacks.isEmpty())c.drawCenteredTextWithShadow(textRenderer,filter.getText().isBlank()?"No hay paquetes todavía.":"No hay coincidencias.",width/2,t+145,0xFFAAAAAA);int visible=10,max=Math.max(0,visiblePacks.size()-visible);scroll=Math.max(0,Math.min(scroll,max));for(int row=0;row<10;row++){ButtonWidget play=playButtons.get(row),del=deleteButtons.get(row);int y=t+86+row*19;play.setPosition(l+338,y-1);del.setPosition(l+362,y-1);boolean exists=row+scroll<visiblePacks.size();play.visible=exists;del.visible=exists;play.active=exists;del.active=exists&&canEdit&&hasShiftDown();if(!exists)continue;CommandPack p=visiblePacks.get(row+scroll);boolean h=mx>=l+10&&mx<l+334&&my>=y-1&&my<y+17;if(h)c.fill(l+9,y-1,l+335,y+17,0xFF30465A);else if(row%2==0)c.fill(l+10,y-1,l+334,y+17,0x40202020);c.drawTextWithShadow(textRenderer,p.name.isBlank()?"(sin nombre)":p.name,l+16,y+1,0xFFFFFFFF);c.drawTextWithShadow(textRenderer,p.commands.size()+" pasos",l+270,y+1,0xFFAAAAAA);}
  if(max>0){int top=t+85,bottom=t+277,track=bottom-top,barH=Math.max(20,track*visible/visiblePacks.size()),barY=top+(track-barH)*scroll/max;c.fill(l+390,top,l+396,bottom,0xFF333333);c.fill(l+390,barY,l+396,barY+barH,0xFFAAAAAA);}if(!runFeedback.isEmpty())c.drawTextWithShadow(textRenderer,runFeedback,l+14,t+283,0xFF55FF55);super.render(c,mx,my,d);}
 @Override public boolean mouseClicked(double mx,double my,int b){int l=width/2-205,t=height/2-150;if(b==0&&mx>=l+378&&mx<l+410&&my>=t&&my<t+32){client.setScreen(null);return true;}List<CommandPack> visible=shown();if(b==0&&visible.size()>10&&mx>=l+387&&mx<=l+400&&my>=t+85&&my<=t+277){draggingScrollbar=true;updateScrollFromMouse(my);return true;}int row=(int)((my-(t+86))/19),i=row+scroll;if(b==0&&row>=0&&row<10&&i<visible.size()&&mx>=l+10&&mx<l+334){client.setScreen(new CommandPackEditorScreen(this,packs,visible.get(i),canEdit));return true;}return super.mouseClicked(mx,my,b);}
 @Override public boolean mouseScrolled(double mx,double my,double h,double v){int l=width/2-205,t=height/2-150;if(mx>=l+9&&mx<l+401&&my>=t+85&&my<t+277){scroll-=(int)Math.signum(v);return true;}return super.mouseScrolled(mx,my,h,v);}
 @Override public boolean mouseDragged(double mx,double my,int button,double dx,double dy){if(draggingScrollbar&&button==0){updateScrollFromMouse(my);return true;}return super.mouseDragged(mx,my,button,dx,dy);}@Override public boolean mouseReleased(double mx,double my,int button){if(button==0&&draggingScrollbar){draggingScrollbar=false;return true;}return super.mouseReleased(mx,my,button);}@Override public boolean shouldPause(){return false;}
 private void updateScrollFromMouse(double y){int max=Math.max(0,shown().size()-10);if(max==0)return;int t=height/2-150,top=t+85,bottom=t+277,track=bottom-top,barH=Math.max(20,track*10/shown().size());double f=(y-top-barH/2.0)/Math.max(1.0,track-barH);scroll=(int)Math.round(Math.max(0,Math.min(1,f))*max);}private static List<CommandPack> decode(String json){List<CommandPack> r=GSON.fromJson(json,TYPE);if(r==null)r=new ArrayList<>();r.sort(Comparator.comparing(p->p.name==null?"":p.name,String.CASE_INSENSITIVE_ORDER));return r;}
}
